  "use strict";
  root.FPPresets = [{"id": "readme-2", "name": "README 2", "timeStep": 0.007, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": -1.275949999999999, "cy": -1.62765, "w": 30.2937, "h": 30.2937, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  v.x = cos(p.y);\nv.y = cos(p.x);\n\n\n  return v;\n}"}, {"id": "readme-1", "name": "README 1", "timeStep": 0.007, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": -1.275949999999999, "cy": -1.6277, "w": 30.2937, "h": 30.2937, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  v.x = length(p)*min(sin(p.y),cos(p.x));\nv.y = cos((p.y+p.y));\n\n\n  return v;\n}"}, {"id": "readme-3", "name": "README 3", "timeStep": 0.02, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0.21419999999999995, "cy": -0.7710999999999997, "w": 55.970200000000006, "h": 55.970200000000006, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  v.x = min(sin(exp(p.x)),sin(length(p)));\nv.y = sin(p.x);\n\n\n  return v;\n}"}, {"id": "readme-4", "name": "README 4", "timeStep": 0.02, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 2.43185, "cy": -1.1695, "w": 11.4385, "h": 11.4385, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  v.x = (p.y+cos(p.y));\nv.y = sin(min(length(p),log((p.y+p.x))*p.x));\n\n\n  return v;\n}"}, {"id": "secret-door", "name": "Secret door", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": -0.15344999999999986, "cy": -0.1291, "w": 7.4611, "h": 7.4611, "code": "// p.x and p.y are current coordinates\n  // v.x and v.y is a velocity at point p\n  vec2 get_velocity(vec2 p) {\n    vec2 v = vec2(0., 0.);\n\n    // change this to get a new vector field\n    v.x = p.y*p.y ;\n    v.y = -p.x*p.x *.05;\n\n    return v;\n  }"}, {"id": "four-counterclockwise-cogs-pushing-parti", "name": "Four counterclockwise cogs pushing particles clockwise :)", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0.7887499999999994, "cy": -0.5769500000000001, "w": 16.3759, "h": 16.3759, "code": "vec2 field(vec2 p) {\n  float d = length(p);\n  return vec2(-p.y, p.x) * exp(-d*d*0.1);\n}\n// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  v = field(p + vec2(-5., 0.)) +\n    field(p + vec2(-2.5, 2.5)) +\n    field(p + vec2(0., 0.)) +\n    field(p + vec2(-2.5, -2.5));\n  return v;\n}"}, {"id": "best-vortex", "name": "Best vortex", "timeStep": 0.01, "fadeOut": 0.9, "dropProbability": 0.009, "colorMode": 2, "cx": -6.158449999999998, "cy": -0.9834499999999995, "w": 96.8415, "h": 96.8415, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  float r = length(p);\nfloat theta = atan(p.y, p.x);\nv = vec2(p.y, -p.x) / r;\nfloat t = sqrt(r * 10.) + theta + frame * .02;\nv *= sin(t);\nv *= length(v) * 10.;\nv += p * .2;\n\n  return v;\n}"}, {"id": "true-dipole", "name": "True Dipole", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0, "cy": 0, "w": 8.5398, "h": 8.5398, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  float x = p.x;\nfloat y = p.y;\n\n// true dipole\nv.x = 2.0*x*y;\nv.y = y*y - x*x;\n\n  return v;\n}"}, {"id": "black-hole", "name": "Black hole", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": -0.47934999999999994, "cy": 0.3591500000000001, "w": 8.5397, "h": 8.5397, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  float a = .1;\nfloat r2 = p.x * p.x + p.y * p.y;\nv = vec2(p.y, -p.x) / r2 - a * p;\n\n  return v;\n}"}, {"id": "beautiful-field", "name": "Beautiful field", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 3, "cx": -1.6564499999999995, "cy": -0.36424999999999974, "w": 24.7317, "h": 24.7317, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  float dt = 0.01;\nfloat t = frame*dt;\nfloat w = 2.*PI/5.;\nfloat A = 2.;\n\nfloat d = sqrt(p.x*p.x + p.y*p.y);\nv.x = A*cos(w*t/d);\nv.y = A*sin(w*t/d);\n\n  return v;\n}"}, {"id": "rain", "name": "Rain", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0, "cy": 0, "w": 8.5398, "h": 8.5398, "code": "bool isUnshadowed(vec2 p) {\n  bool upper = length(p) > 1.0 && p.y > 0.0;\n  bool lower = length(p) > 1.0 && p.y < 0.0 && abs(p.x) > 1.0;\n  return upper || lower;\n}\n\nvec2 unshadowedV(vec2 p) {\n  return vec2(0.0,-3.0+p.y);\n}\n\nbool isSpray(vec2 p) {\n  return length(p) > 1.0 && abs(p.x) < 1.0;\n}\n\nvec2 sprayV(vec2 p) {\n  float vy = -1.0+p.y;\n  float vx = p.x > 0.0 ? (1.0-p.x)/vy : (-1.0-p.x)/vy;\n  return vec2(vx,vy);\n}\n\nbool isCircle(vec2 p) {\n  return length(p) > 1.0 && length(p) < 1.05;\n}\n\nvec2 circleV(vec2 p) {\n  vec2 v = vec2(0., 0.);\n  v.x = sign(p.x)* p.y;\n  v.y = -abs(p.x);\n  return v;\n}\n\n// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  v = isCircle(p) ? circleV(p) :\n      isUnshadowed(p) ? unshadowedV(p) :\n      isSpray(p) ? sprayV(p) : vec2(1.0/0.0,1.0/0.0);\n\n  return v;\n}"}, {"id": "hyperjump", "name": "Hyperjump", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 2, "cx": 0.523299999999999, "cy": 1.2703999999999995, "w": 48.3842, "h": 48.3842, "code": "vec2 circle(vec2 p, vec2 c) {\n  vec2 c0 = p - c;\n  vec2 p0 = vec2(-c0.y, c0.x);\n  float l = length(p0);\n  return p0 * exp(-l*sin(frame*0.01));\n}\n// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = circle(p, vec2(0., 0.));\n\n  float r = 7.;\n  for (int i = 0; i < 2; ++i) {\n    float a = 0.01 * frame + float(i) * 2.*PI/7.;\n    v += circle(p, vec2(r * cos(a) , r * sin(a)));\n  }\n  return v;\n}"}, {"id": "particle-grinder", "name": "Particle Grinder", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0.028149999999999675, "cy": 0.08830000000000005, "w": 9.045300000000001, "h": 9.045300000000001, "code": "vec2 tensor(vec2 p, vec2 c0, vec4 abcd, float N) {\n  vec2 p0 = p - c0;\n  float theta = atan(p0.y, p0.x);\n  float c = cos(N * theta);\n  float s = sin(N * theta);\n  return length(p0) * vec2(abcd[2] * c + abcd[3] * s,\n              abcd[0] * c + abcd[1] * s);\n}\n\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n  v = tensor(p, vec2(0., 0.), vec4(-2., 0., 0., 1.), 2.);\n  return v;\n}"}, {"id": "reflecting-pool", "name": "Reflecting pool", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0, "cy": 0, "w": 8.5398, "h": 8.5398, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  v.x = sin(5.0*p.y + p.x);\nv.y = cos(5.0*p.x - p.y);\n\n  return v;\n}"}, {"id": "shear-zone", "name": "Shear zone", "timeStep": 0.01, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": 0, "cy": 0, "w": 8.539734222673566, "h": 8.539734222673566, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  float r = length(p) - 1.5;\nfloat c = 1.0/(1.0+exp(-5.0*r));\nfloat vx1 = -p.y,  // circle\n      vy1 = p.x;\nfloat vx2 = 0.2*p.x+p.y, // spiral\n      vy2 = 0.2*p.y-p.x;\nv.x = c*vx1 + (1.0-c)*vx2;\nv.y = c*vy1 + (1.0-c)*vy2;\n\n\n  return v;\n}"}, {"id": "julia-set", "name": "Julia set", "timeStep": 0.004, "fadeOut": 0.998, "dropProbability": 0.009, "colorMode": 1, "cx": -0.40235, "cy": -0.01795000000000002, "w": 5.0845, "h": 5.0845, "code": "// p.x and p.y are current coordinates\n// v.x and v.y is a velocity at point p\nvec2 get_velocity(vec2 p) {\n  vec2 v = vec2(0., 0.);\n\n  // change this to get a new vector field\n  vec2 c = p;\nvec2 z = vec2(.4, .5);\nfor (int i = 0; i < 8; i++) {\n   c = vec2(c.x * c.x - c.y * c.y, c.y * c.x + c.x * c.y);\n   c += z;\n}\nv = c;\n\n\n  return v;\n}"}];
